/**
 * rate-limit-config.ts - 限流配置中心（TypeScript 源文件 - Sprint 50 新增）
 *
 * 目标：
 *   - 解决 Sprint 17 单一 DEFAULT_RISK_RATE_LIMIT_CONFIG 局限
 *   - 支持按业务类型差异化（payment 更严，evaluation 更宽）
 *   - 配置可热更新（db 集合 rate_limit_configs 优先于默认值）
 *   - 配置带 TTL 缓存，避免每次请求都查 db
 *
 * 配置优先级（从高到低）：
 *   1. 调用方显式传入的 config
 *   2. db 集合 rate_limit_configs 中的 type 匹配记录
 *   3. 内置 BUSINESS_TYPE_DEFAULT_CONFIG
 *   4. 兜底 DEFAULT_RISK_RATE_LIMIT_CONFIG
 *
 * db 集合结构（rate_limit_configs）：
 *   {
 *     _id:           string           // 业务类型（order / payment / refund / evaluation / mall_order / activity_apply / ...）
 *     perUserPerMinute: number
 *     perUserPerTargetPerMinute: number
 *     windowMs:      number
 *     enabled:       boolean          // false 时跳过限流（紧急关停）
 *     description:   string
 *     updatedAt:     number
 *     updatedBy:     string
 *   }
 *
 * 用法：
 *   import { getRateLimitConfig, initRateLimitConfigStore, clearRateLimitConfigCache } from './rate-limit-config'
 *   initRateLimitConfigStore({ collection: db.collection('rate_limit_configs'), command: db.command })
 *
 *   // 自动按 type 查找：
 *   const cfg = await getRateLimitConfig('payment')
 *
 *   // 热更新：调用方清缓存或等待 TTL 过期
 *   clearRateLimitConfigCache()
 *
 * 设计取舍：
 *   - 缓存 TTL 30s（业务可配），避免每次请求查 db
 *   - enabled=false 表示紧急关停（无需修改代码即可放行）
 *   - 配置查表不存在的 type 走兜底值（向前兼容）
 *
 * 编译方式：
 *   npx --yes -p typescript@5.4.5 tsc -p tsconfig.common.json
 */

import { DEFAULT_RISK_RATE_LIMIT_CONFIG, type RateLimitConfig } from './risk-rate-limit'

// ===== 类型定义 =====

/** 已知业务类型 */
export type KnownBusinessType =
  | 'order'
  | 'payment'
  | 'refund'
  | 'evaluation'
  | 'mall_order'
  | 'activity_apply'
  | 'boarding_accept'
  | string

/** db 中存储的扩展配置（含 enabled / 元数据）*/
export interface RateLimitConfigRecord {
  _id: string
  perUserPerMinute: number
  perUserPerTargetPerMinute: number
  windowMs: number
  enabled: boolean
  description?: string
  updatedAt?: number
  updatedBy?: string
}

/** db 句柄 + db.command 引用 */
export interface RateLimitConfigStore {
  collection: any
  command: any
  collectionName?: string
}

/** 配置查找结果 */
export interface RateLimitConfigResult {
  config: RateLimitConfig
  /** 配置来源（db / default / fallback） */
  source: 'db' | 'business_default' | 'fallback'
  /** 业务类型是否启用（db 记录 enabled=false 时） */
  enabled: boolean
}

// ===== 业务类型差异化默认值 =====

/**
 * 内置业务类型默认配置
 *  - payment / refund: 严（防滥用）
 *  - evaluation: 中（防刷量）
 *  - order: 中（防恶意下单）
 *  - mall_order / activity_apply: 中（防库存耗尽）
 *  - boarding_accept: 严（防商家账号被盗批量接单）
 */
export const BUSINESS_TYPE_DEFAULT_CONFIG: Record<string, RateLimitConfig> = Object.freeze({
  payment: Object.freeze({
    perUserPerMinute: 5,
    perUserPerTargetPerMinute: 3,
    windowMs: 60 * 1000,
  }),
  refund: Object.freeze({
    perUserPerMinute: 3,
    perUserPerTargetPerMinute: 2,
    windowMs: 60 * 1000,
  }),
  order: Object.freeze({
    perUserPerMinute: 10,
    perUserPerTargetPerMinute: 5,
    windowMs: 60 * 1000,
  }),
  evaluation: Object.freeze({
    perUserPerMinute: 10,
    perUserPerTargetPerMinute: 5,
    windowMs: 60 * 1000,
  }),
  mall_order: Object.freeze({
    perUserPerMinute: 8,
    perUserPerTargetPerMinute: 4,
    windowMs: 60 * 1000,
  }),
  activity_apply: Object.freeze({
    perUserPerMinute: 5,
    perUserPerTargetPerMinute: 3,
    windowMs: 60 * 1000,
  }),
  boarding_accept: Object.freeze({
    perUserPerMinute: 3,                // 严：每分钟最多 3 次接单
    perUserPerTargetPerMinute: 2,       // 同一订单最多 2 次
    windowMs: 60 * 1000,
  }),
})

/** 缓存 TTL（毫秒） */
const DEFAULT_CACHE_TTL_MS = 30 * 1000

// ===== 内存缓存 =====

interface CacheEntry {
  config: RateLimitConfig
  enabled: boolean
  source: 'db' | 'business_default' | 'fallback'
  expiresAt: number
}

const _cache: Map<string, CacheEntry> = new Map()
let _cacheTtlMs = DEFAULT_CACHE_TTL_MS

/**
 * 设置缓存 TTL
 */
export function setRateLimitConfigCacheTtl(ttlMs: number): void {
  _cacheTtlMs = Math.max(1000, ttlMs)
}

/**
 * 获取缓存 TTL
 */
export function getRateLimitConfigCacheTtl(): number {
  return _cacheTtlMs
}

/**
 * 清空配置缓存（强制下次查询走 db 或默认值）
 */
export function clearRateLimitConfigCache(type?: string): void {
  if (type) {
    _cache.delete(type)
  } else {
    _cache.clear()
  }
}

/**
 * 读取缓存统计（监控/调试）
 */
export function getCacheStats(): { keys: number; ttlMs: number } {
  return {
    keys: _cache.size,
    ttlMs: _cacheTtlMs,
  }
}

// ===== 全局存储句柄 =====

let _store: RateLimitConfigStore | null = null

/**
 * 注入全局配置存储
 *
 * 用法（在云函数入口）：
 *   const db = cloudbase.database()
 *   initRateLimitConfigStore({ collection: db.collection('rate_limit_configs'), command: db.command })
 */
export function initRateLimitConfigStore(store: RateLimitConfigStore | null): void {
  _store = store
}

export function getRateLimitConfigStore(): RateLimitConfigStore | null {
  return _store
}

// ===== 核心：配置查找 =====

/**
 * 验证 RateLimitConfig 数值合法性
 */
function validateConfig(cfg: unknown, source: string): RateLimitConfig {
  if (!cfg || typeof cfg !== 'object') {
    throw new Error(`[rate-limit-config] invalid config from ${source}: not an object`)
  }
  const c = cfg as Record<string, unknown>
  const perUserPerMinute = Number(c.perUserPerMinute)
  const perUserPerTargetPerMinute = Number(c.perUserPerTargetPerMinute)
  const windowMs = Number(c.windowMs)
  if (!Number.isFinite(perUserPerMinute) || perUserPerMinute <= 0) {
    throw new Error(`[rate-limit-config] invalid perUserPerMinute: ${perUserPerMinute}`)
  }
  if (!Number.isFinite(perUserPerTargetPerMinute) || perUserPerTargetPerMinute <= 0) {
    throw new Error(`[rate-limit-config] invalid perUserPerTargetPerMinute: ${perUserPerTargetPerMinute}`)
  }
  if (!Number.isFinite(windowMs) || windowMs <= 0) {
    throw new Error(`[rate-limit-config] invalid windowMs: ${windowMs}`)
  }
  return {
    perUserPerMinute,
    perUserPerTargetPerMinute,
    windowMs,
  }
}

/**
 * 从 db 读取配置（带超时保护）
 */
async function _readFromDb(type: string): Promise<RateLimitConfigRecord | null> {
  if (!_store || !_store.collection) {return null}
  const coll = _store.collection
  try {
    const res = await coll.doc(type).get()
    if (!res || !res.data) {return null}
    const data = Array.isArray(res.data) ? res.data[0] : res.data
    return (data && data._id) ? (data as RateLimitConfigRecord) : null
  } catch (e) {
    return null
  }
}

/**
 * 同步：根据业务类型返回默认配置（仅用于初始化 / 缓存未命中时降级）
 */
function _getBusinessDefault(type: string): {
  config: RateLimitConfig
  source: 'business_default' | 'fallback'
} {
  if (Object.prototype.hasOwnProperty.call(BUSINESS_TYPE_DEFAULT_CONFIG, type)) {
    return {
      config: BUSINESS_TYPE_DEFAULT_CONFIG[type],
      source: 'business_default',
    }
  }
  return {
    config: DEFAULT_RISK_RATE_LIMIT_CONFIG,
    source: 'fallback',
  }
}

/**
 * 异步：按业务类型查找配置（缓存优先 → db → 默认值）
 *
 * 流程：
 *   1. 缓存命中且未过期 → 直接返回
 *   2. 缓存未命中或已过期：
 *      a. db 中有记录 → 验证后写入缓存
 *      b. db 中无记录 → 走 BUSINESS_TYPE_DEFAULT_CONFIG / DEFAULT_RISK_RATE_LIMIT_CONFIG
 *   3. 返回结果 + source 标记
 *
 * @throws 当 db 中存储的 config 数值不合法时
 */
export async function getRateLimitConfig(type: string): Promise<RateLimitConfigResult> {
  if (!type || typeof type !== 'string') {
    return {
      config: DEFAULT_RISK_RATE_LIMIT_CONFIG,
      source: 'fallback',
      enabled: true,
    }
  }
  // 1. 缓存命中
  const cached = _cache.get(type)
  const now = Date.now()
  if (cached && cached.expiresAt > now) {
    return {
      config: cached.config,
      source: cached.source,
      enabled: cached.enabled,
    }
  }
  // 2. 尝试 db
  if (_store) {
    const rec = await _readFromDb(type)
    if (rec) {
      try {
        const validated = validateConfig(rec, 'db')
        const enabled = rec.enabled !== false // 缺省值 true
        _cache.set(type, {
          config: validated,
          enabled,
          source: 'db',
          expiresAt: now + _cacheTtlMs,
        })
        return { config: validated, source: 'db', enabled }
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn(
          `[rate-limit-config] db config for "${type}" invalid, fallback:`,
          e && (e as Error).message
        )
      }
    }
  }
  // 3. 默认值
  const def = _getBusinessDefault(type)
  _cache.set(type, {
    config: def.config,
    enabled: true,
    source: def.source,
    expiresAt: now + _cacheTtlMs,
  })
  return { config: def.config, source: def.source, enabled: true }
}

/**
 * 同步版本：仅查缓存或默认值，不查 db
 *  - 用于启动期或 db 不可用时的兜底
 *  - 注意：会写入缓存，使后续同步调用也能命中
 */
export function getRateLimitConfigSync(type: string): RateLimitConfigResult {
  if (!type || typeof type !== 'string') {
    return {
      config: DEFAULT_RISK_RATE_LIMIT_CONFIG,
      source: 'fallback',
      enabled: true,
    }
  }
  const cached = _cache.get(type)
  const now = Date.now()
  if (cached && cached.expiresAt > now) {
    return { config: cached.config, source: cached.source, enabled: cached.enabled }
  }
  const def = _getBusinessDefault(type)
  // 写入缓存（同步版也写，避免每次调用都走 fallback）
  _cache.set(type, {
    config: def.config,
    enabled: true,
    source: def.source,
    expiresAt: now + _cacheTtlMs,
  })
  return { config: def.config, source: def.source, enabled: true }
}

// ===== 工具：管理接口 =====

/**
 * 列出所有已知业务类型
 */
export function listKnownBusinessTypes(): string[] {
  return Object.keys(BUSINESS_TYPE_DEFAULT_CONFIG)
}

/**
 * 快速从 db 实例初始化
 *
 * 用法：
 *   const cloudbase = require('wx-server-sdk')
 *   cloudbase.init({ env: cloudbase.DYNAMIC_CURRENT_ENV })
 *   const db = cloudbase.database()
 *   initRateLimitConfigFromDb(db, { collectionName: 'rate_limit_configs' })
 */
export function initRateLimitConfigFromDb(
  db: any,
  options: { collectionName?: string; command?: any } = {}
): boolean {
  if (!db) {return false}
  try {
    const coll = db.collection(options.collectionName || 'rate_limit_configs')
    const command = options.command || (db.command)
    initRateLimitConfigStore({ collection: coll, command, collectionName: options.collectionName })
    return true
  } catch (e) {
    // eslint-disable-next-line no-console
    console.warn('[rate-limit-config] init from db failed:', e && (e as Error).message)
    return false
  }
}

/**
 * 获取某个业务类型的快照（用于管理面板 / 调试）
 */
export async function getConfigSnapshot(type: string): Promise<{
  type: string
  effective: RateLimitConfig
  source: 'db' | 'business_default' | 'fallback'
  enabled: boolean
  dbRecord: RateLimitConfigRecord | null
  cached: boolean
}> {
  const effective = await getRateLimitConfig(type)
  const cached = _cache.has(type)
  let dbRecord: RateLimitConfigRecord | null = null
  if (_store) {
    dbRecord = await _readFromDb(type)
  }
  return {
    type,
    effective: effective.config,
    source: effective.source,
    enabled: effective.enabled,
    dbRecord,
    cached,
  }
}

// ===== 默认导出 =====

export default {
  BUSINESS_TYPE_DEFAULT_CONFIG,
  initRateLimitConfigStore,
  getRateLimitConfigStore,
  setRateLimitConfigCacheTtl,
  getRateLimitConfigCacheTtl,
  clearRateLimitConfigCache,
  getCacheStats,
  getRateLimitConfig,
  getRateLimitConfigSync,
  getConfigSnapshot,
  listKnownBusinessTypes,
  initRateLimitConfigFromDb,
}
